{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative (sentiment < 0) or shows early negative signals.",
    "Reduce forecast overshoots following sharp price spikes by applying a 10-15% dampening factor to the immediate next period.",
    "Apply mean reversion bias: if forecast is consistently above true outcome over 5+ days, reduce forecast by 2-5% per day.",
    "Increase forecast sensitivity to recent true outcomes when sentiment is neutral or positive (sentiment = 0) to avoid lag.",
    "For long-term horizons (>10 days), apply a smoothing filter to reduce volatility and avoid overreaction to short-term noise.",
    "When sentiment is positive and forecast is below true outcome, increase forecast by 3-5% to align with bullish momentum."
  ]
}
